SELECT 'source_name_collisions' measure,count(*) n FROM (SELECT lower(regexp_replace(regexp_replace(name,'[^[:alnum:] ]',' ','g'),'\s+',' ','g')) FROM source_product WHERE superseded_at IS NULL GROUP BY 1 HAVING count(DISTINCT source_record_ref)>1) t;
SELECT count(*) total, count(*) FILTER(WHERE product_number IS NOT NULL AND product_number<>'') product_number, count(*) FILTER(WHERE sku IS NOT NULL AND sku<>'') sku FROM canonical_sale_item WHERE superseded_at IS NULL;
SELECT category_name,count(DISTINCT item_name) names,min(trading_date),max(trading_date) FROM canonical_sale_item WHERE superseded_at IS NULL GROUP BY 1 ORDER BY 2 DESC;
SELECT sale_item_stock_description,string_agg(DISTINCT recipe_id::text,','),string_agg(DISTINCT recipe_name,' | '),string_agg(DISTINCT recipe_folder_name,' | ') FROM canonical_sale_recipe_link WHERE superseded_at IS NULL GROUP BY 1 HAVING count(DISTINCT recipe_id)>1;
SELECT item_name, string_agg(DISTINCT category_name,' | ') categories,min(trading_date),max(trading_date),count(*) lines FROM canonical_sale_item WHERE superseded_at IS NULL AND item_name ~* 'latte|breakfast|cafe|café|porterhouse|t-shirt|merch|extra shot|oat milk' GROUP BY 1 ORDER BY 5 DESC LIMIT 35;
SELECT product_name_key,quantity,cost,reason,unit_of_measurement_name,recipe_id FROM canonical_wastage WHERE superseded_at IS NULL AND (recipe_id IS NULL OR product_name_key ~* 'beef|chicken|bread|milk|fish|chips') ORDER BY product_name_key LIMIT 35;
SELECT count(*) definitions,count(*) FILTER(WHERE active) active,count(*) FILTER(WHERE production_item) production,count(DISTINCT folder_id) folders FROM canonical_recipe_definition WHERE superseded_at IS NULL;
SELECT count(*) stocks,count(stock_id) ids,count(supplier_name) suppliers FROM canonical_recipe_definition_stocks s JOIN canonical_recipe_definition d ON d.id=s.snapshot_id WHERE superseded_at IS NULL;
SELECT a.status,c.name,count(*) names,sum(abs(s.amount)) absolute_amount FROM resolved_product_sales s JOIN product_category_assignment a USING(product_name_key) JOIN product_category c ON c.id=a.product_category_id WHERE trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1,2 ORDER BY 4 DESC;
